import type { Chapter, Topic } from "@/lib/study/schema";

/**
 * Algorithms → Asymptotics and recurrences; Searching and sorting (CLRS ch. 2–4, 6–8). Numbers from lib/study/algo.ts, checked by script:
 * n = 16: log n 4, √n 4, n log n 64, n² 256, n³ 4096, 2ⁿ 65 536. 2ⁿ ≥ n³ from n = 10; n² ≥ 100 n log₂ n from n = 997.
 * Recursion tree n = 16: 2T(n/2)+n levels 16 ×5 = 80; 4T(n/2)+n levels 16 32 64 128 256 = 496; T(n/2)+n levels 16 8 4 2 1 = 31.
 * Master: 2T(n/2)+n Θ(n log n); 8T(n/2)+n² Θ(n³); 7T(n/2)+n² Θ(n^2.807); 2T(n/2)+n² Θ(n²); T(n/2)+1 Θ(log n); 4T(n/2)+n² log n Θ(n² log² n);
 * 3T(n/4)+n Θ(n); 2T(n/4)+√n Θ(√n log n); 2T(n/2)+n/log n Θ(n log log n); 16T(n/4)+n² Θ(n² log n).
 * 5 2 4 6 1 3: 9 inversions; bubble 15 comparisons 9 swaps; selection 15 comparisons 3 swaps; insertion 12 comparisons 9 shifts.
 * Insertion on sorted 5 keys: 4 comparisons; on reversed 5: 10. Merge sort 38 27 43 3 9 82 10: 14 comparisons, 11 inversions; 8 sorted or reversed keys: 12.
 * Quicksort (Lomuto) 2 8 7 1 3 5 6 4: first partition 2 1 3 4 7 5 6 8, 15 comparisons, 6 swaps; sorted 6 keys: 15 comparisons, depth 5.
 * ⌈log₂ n!⌉: n 3 → 3, 4 → 5, 5 → 7, 6 → 10, 10 → 22, 12 → 29. Radix 170 45 75 90 802 24 2 66 in 3 passes; counting sort 2 5 3 0 2 3 0 3 → 0 0 2 2 3 3 3 5.
 */
